// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Easing, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level Google Font loading
const { fontFamily: interFamily } = loadInter("normal", {
  weights: ["400", "900"],
});



export type StepVerticalStackProps = Record<string, any>;

const StepVerticalStack: React.FC<StepVerticalStackProps> = ({
  backgroundColor = "#0E0E0F",
  transparentBackground = false,
  durationInSeconds = 5,
  steps = [
    { number: "01", label: "Open Google Ads" },
    { number: "02", label: "Tools and measurement" },
    { number: "03", label: "Attribution" },
    { number: "04", label: "Model comparison report" },
  ],
  stepDelayMs = 400,
  ruleDelayMs = 80,
  highlightWord = "report",
  highlightColor = "#D4571E",
  textColorActive = "#FFFFFF",
  textColorInactive = "#6B6B6B",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Responsive scale factor based on 1080p canvas baseline
  const scaleFactor = height / 1080;

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timing calculations
  const stepDelayFrames = (stepDelayMs / 1000) * fps;
  const ruleDelayFrames = (ruleDelayMs / 1000) * fps;
  const entryDurationInFrames = 0.55 * fps;
  const exitDurationInFrames = 0.40 * fps;

  const totalFrames = durationInSeconds * fps;
  const exitStartFrame = totalFrames - exitDurationInFrames;

  // Global exit fade animation
  const exitOpacity = interpolate(
    frame,
    [exitStartFrame, totalFrames],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.16, 1, 0.3, 1),
    }
  );

  // Helper function to handle text word-level highlighting
  const renderLabel = (
    text: string,
    isStep4: boolean,
    wordToHighlight: string,
    highlightClr: string,
    baseClr: string
  ) => {
    if (!isStep4 || !wordToHighlight) {
      return text;
    }
    const parts = text.split(new RegExp(`(${wordToHighlight})`, "gi"));
    return (
      <>
        {parts.map((part, index) => {
          const isMatch = part.toLowerCase() === wordToHighlight.toLowerCase();
          return (
            <span
              key={index}
              style={{
                color: isMatch ? highlightClr : baseClr,
                transition: "none",
              }}
            >
              {part}
            </span>
          );
        })}
      </>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: interFamily,
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          width: 800 * scaleFactor,
          transition: "none",
        }}
      >
        {steps.map((step, index) => {
          const isLastStep = index === steps.length - 1;

          // Compute individual Step Entry Timings
          const stepEntryStart = index * stepDelayFrames;
          const stepEntryEnd = stepEntryStart + entryDurationInFrames;

          const entryOpacity = interpolate(
            frame,
            [stepEntryStart, stepEntryEnd],
            [0, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.bezier(0.16, 1, 0.3, 1),
            }
          );

          const entryTranslateY = interpolate(
            frame,
            [stepEntryStart, stepEntryEnd],
            [18 * scaleFactor, 0],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.bezier(0.16, 1, 0.3, 1),
            }
          );

          const entryScale = interpolate(
            frame,
            [stepEntryStart, stepEntryEnd],
            [1.0, 1.08],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.bezier(0.16, 1, 0.3, 1),
            }
          );

          // Combined step opacity (entry * exit)
          const stepOpacity = entryOpacity * exitOpacity;

          // CSS variables for clean step transition states
          const currentStepColor = isLastStep ? textColorActive : textColorInactive;
          const stepTransform = isLastStep
            ? `scale(${entryScale})`
            : `translateY(${entryTranslateY}px)`;

          // Compute Rule Timing (Rule i is below Step i, fades 80ms after Step i)
          const ruleEntryStart = stepEntryStart + ruleDelayFrames;
          const ruleEntryEnd = ruleEntryStart + entryDurationInFrames;

          const ruleEntryOpacity = interpolate(
            frame,
            [ruleEntryStart, ruleEntryEnd],
            [0, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.bezier(0.16, 1, 0.3, 1),
            }
          );

          const ruleOpacity = ruleEntryOpacity * exitOpacity;

          return (
            <React.Fragment key={index}>
              <div
                style={{
                  display: "flex",
                  flexDirection: "row",
                  alignItems: "center",
                  justifyContent: "flex-start",
                  width: "100%",
                  opacity: stepOpacity,
                  transform: stepTransform,
                  transformOrigin: "center center",
                  transition: "none",
                }}
              >
                {/* Step Number */}
                <div
                  style={{
                    fontFamily: interFamily,
                    fontWeight: 900,
                    fontSize: 72 * scaleFactor,
                    letterSpacing: "-0.02em",
                    color: currentStepColor,
                    width: 120 * scaleFactor,
                    textAlign: "left",
                    transition: "none",
                  }}
                >
                  {step.number}
                </div>

                {/* Step Label */}
                <div
                  style={{
                    fontFamily: interFamily,
                    fontWeight: 400,
                    fontSize: 48 * scaleFactor,
                    letterSpacing: "0.01em",
                    color: currentStepColor,
                    transition: "none",
                  }}
                >
                  {renderLabel(
                    step.label,
                    isLastStep,
                    highlightWord,
                    highlightColor,
                    currentStepColor
                  )}
                </div>
              </div>

              {/* Step Divider Rule (fades with delay relative to its parent step) */}
              {!isLastStep && (
                <div
                  style={{
                    width: "100%",
                    height: 2 * scaleFactor,
                    backgroundColor: textColorInactive,
                    opacity: ruleOpacity,
                    marginTop: 24 * scaleFactor,
                    marginBottom: 24 * scaleFactor,
                    transition: "none",
                  }}
                />
              )}
            </React.Fragment>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default StepVerticalStack;